"""Data-wise proof of the NN architecture: on data generated by an Integrated Random Walk (as eda.py proves
the real TVT is), the IRW integration head must (1) recover the trajectory on a held-out toe and (2) beat a
free-per-row output baseline — i.e. the proof-derived structure genuinely helps. Pure GPU torch."""
import torch, torch.nn as nn
import nn_statespace as M
DEV = M.DEV

def _sim_irw(B=64, L=400, qs=0.05, qv=0.002, seed=0):
    g = torch.Generator(device=DEV).manual_seed(seed)
    v = torch.zeros(B, L, device=DEV); s = torch.zeros(B, L, device=DEV)
    for i in range(1, L):
        v[:, i] = v[:, i-1] + torch.randn(B, generator=g, device=DEV) * qv**0.5
        s[:, i] = s[:, i-1] + v[:, i-1] + torch.randn(B, generator=g, device=DEV) * qs**0.5
    ps = L // 3
    obs_incr = (s[:, 1:] - s[:, :-1])                                  # local slope (like GR-informed dip)
    obs_incr = torch.cat([obs_incr[:, :1], obs_incr], 1)
    obs = obs_incr + torch.randn(B, L, generator=g, device=DEV) * 0.02  # noisy observation
    x = obs.unsqueeze(-1)                                               # (B,L,1) feature
    ctx = torch.stack([obs.mean(1), obs.std(1)], 1)                     # per-well context
    anchor = s[:, ps]
    dtvt = s - s[:, ps:ps+1]                                            # target trajectory
    mask = torch.zeros(B, L, device=DEV); mask[:, ps:] = 1              # hidden = toe
    return x, ctx, anchor, dtvt, mask, ps

class FreeNet(nn.Module):                                               # baseline: direct per-row output (no integration)
    def __init__(s, f, c, h=96):
        super().__init__(); s.film = M.PerWellFiLM(c, f)
        s.gru = nn.GRU(f, h, 2, batch_first=True, bidirectional=True, dropout=0.1)
        s.out = nn.Linear(2*h, 1)
    def forward(s, x, ctx, anchor):
        x = s.film(x, ctx); h,_ = s.gru(x); return s.out(h).squeeze(-1), torch.zeros_like(x[...,0])

def _train(net, data, iters=250, irw=True):
    x, ctx, anchor, dtvt, mask, ps = data
    opt = torch.optim.Adam(net.parameters(), 3e-3)
    for _ in range(iters):
        pred, logv = net(x, ctx, anchor)
        if irw: loss = M.student_t_nll(pred, logv, dtvt, mask)
        else:   loss = ((pred - dtvt)**2 * mask).sum()/mask.sum()
        opt.zero_grad(); loss.backward(); opt.step()
    with torch.no_grad():
        pred, _ = net(x, ctx, anchor)
        return (((pred - dtvt)**2 * mask).sum()/mask.sum()).sqrt().item()

def test_irw_beats_free():
    tr = _sim_irw(seed=0); te = _sim_irw(seed=1)
    ss = M.build(1, 2); rmse_irw = _train(ss, tr, irw=True)
    # eval IRW net on held-out toe of a fresh sim
    with torch.no_grad():
        x,ctx,anchor,dtvt,mask,ps = te; p,_ = ss(x,ctx,anchor)
        irw_test = (((p-dtvt)**2*mask).sum()/mask.sum()).sqrt().item()
    fr = FreeNet(1,2).to(DEV); _train(fr, tr, irw=False)
    with torch.no_grad():
        p,_ = fr(x,ctx,anchor); free_test = (((p-dtvt)**2*mask).sum()/mask.sum()).sqrt().item()
    sig = (dtvt*mask).std().item()                          # signal scale on the toe
    print(f"toe RMSE — IRW head {irw_test:.3f} vs free baseline {free_test:.3f} (signal std {sig:.2f})")
    assert irw_test < free_test, (irw_test, free_test)     # proof-derived structure wins
    assert irw_test < 0.5 * sig                             # recovers >75% of the variance

if __name__ == "__main__":
    test_irw_beats_free(); print("PASS")
